// ─── CSV UPLOAD (for devices without HTTP push) ───────────────────────────────

/**
 * POST /api/v1/fingerprint/attendance/upload-csv
 * Admin downloads attendance log from MORX software → uploads CSV here.
 *
 * Supported MORX CSV column formats (auto-detected):
 *   User ID / No. / EmpCode / DeviceUserID  → deviceUserId
 *   Date Time / DateTime / Time / Punch Time → punchTime
 *   Device / DeviceName / DeviceID          → optional, for multi-device files
 *
 * Body (multipart/form-data):
 *   file     → CSV file
 *   deviceId → which registered device this CSV came from (ObjectId)
 */
exports.uploadAttendanceCSV = async (req, res) => {
  try {
    const { deviceId } = req.body;
    if (!req.file) return res.status(400).json({ success: false, message: 'CSV file required' });
    if (!deviceId) return res.status(400).json({ success: false, message: 'deviceId required (select which device this CSV is from)' });

    // Verify device belongs to this school
    const device = await DeviceRegistration.findOne({ _id: deviceId, schoolId: req.schoolId });
    if (!device) return res.status(404).json({ success: false, message: 'Device not found' });

    // ── Parse CSV from buffer ────────────────────────────────────────────────
    const csvText = req.file.buffer.toString('utf-8');
    const lines = csvText.split(/\r?\n/).filter(l => l.trim());
    if (lines.length < 2) return res.status(400).json({ success: false, message: 'CSV is empty or has no data rows' });

    // Parse header row — normalize to lowercase, trim spaces
    const headers = lines[0].split(',').map(h => h.trim().toLowerCase().replace(/[^a-z0-9]/g, ''));

    // Detect column indices (flexible — handles different MORX software versions)
    const findCol = (...names) => {
      for (const name of names) {
        const idx = headers.indexOf(name.toLowerCase().replace(/[^a-z0-9]/g, ''));
        if (idx !== -1) return idx;
      }
      return -1;
    };

    const userIdCol   = findCol('userid', 'no', 'empcode', 'deviceuserid', 'id', 'enrollno');
    const timeCol     = findCol('datetime', 'date time', 'punchtime', 'time', 'checktime', 'timestamp');

    if (userIdCol === -1 || timeCol === -1) {
      return res.status(400).json({
        success: false,
        message: `Could not detect required columns. Found headers: [${headers.join(', ')}]. Need: User ID (or No/EmpCode) AND DateTime (or Time/PunchTime)`,
      });
    }

    // ── Process each data row ────────────────────────────────────────────────
    const results = { processed: 0, skipped: 0, errors: [] };

    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].split(',').map(c => c.trim().replace(/^"|"$/g, '')); // strip quotes
      const deviceUserId = cols[userIdCol]?.trim();
      const rawTime      = cols[timeCol]?.trim();

      if (!deviceUserId || !rawTime) {
        results.errors.push(`Row ${i + 1}: Missing user ID or time — skipped`);
        results.skipped++;
        continue;
      }

      const punchTime = new Date(rawTime);
      if (isNaN(punchTime.getTime())) {
        results.errors.push(`Row ${i + 1}: Invalid date "${rawTime}" — skipped`);
        results.skipped++;
        continue;
      }

      // Find faculty mapping
      const mapping = await FacultyDeviceMapping.findOne({
        schoolId: req.schoolId,
        deviceId: device._id,
        deviceUserId: String(deviceUserId),
        isActive: true,
      });

      if (!mapping) {
        results.errors.push(`Row ${i + 1}: No mapping for deviceUserId="${deviceUserId}" — skipped`);
        results.skipped++;
        continue;
      }

      // Upsert attendance record (same logic as worker)
      const dateOnly = new Date(punchTime.getFullYear(), punchTime.getMonth(), punchTime.getDate());

      const existing = await FacultyAttendance.findOne({
        schoolId: req.schoolId,
        facultyId: mapping.facultyId,
        date: dateOnly,
      });

      const rawPunchEntry = {
        time: punchTime,
        deviceUserId: String(deviceUserId),
        deviceId: device._id,
        queueJobId: `csv-upload-row-${i}`,
      };

      if (!existing) {
        await FacultyAttendance.create({
          schoolId: req.schoolId,
          facultyId: mapping.facultyId,
          date: dateOnly,
          punchIn: punchTime,
          source: 'device',
          rawPunches: [rawPunchEntry],
        });
      } else {
        existing.rawPunches.push(rawPunchEntry);
        if (!existing.punchOut || punchTime > existing.punchOut) existing.punchOut = punchTime;
        if (existing.punchIn && punchTime < existing.punchIn) existing.punchIn = punchTime;
        await existing.save(); // triggers pre-save: recalculates totalHours + status
      }

      results.processed++;
    }

    // Update device stats
    await DeviceRegistration.findByIdAndUpdate(deviceId, {
      lastPingAt: new Date(),
      $inc: { totalPunches: results.processed },
    });

    res.json({
      success: true,
      message: `CSV processed: ${results.processed} punches recorded, ${results.skipped} skipped`,
      data: results,
    });
  } catch (err) {
    console.error('[uploadAttendanceCSV] Error:', err.message);
    res.status(500).json({ success: false, message: err.message });
  }
};
